python3 -c "import pandas as pd; import numpy as np; train = pd.read_csv('train.csv'); X = train.drop('target', axis=1).values; y = train['target'].values; best_acc = 0;
for i in range(X.shape[1]):
    thresh = np.median(X[:, i]);
    acc = np.mean((X[:, i] > thresh) == y);
    acc = max(acc, 1 - acc);
    if acc > best_acc:
        best_acc = acc;
        print(f'Feature {i}, acc {acc}')"

